(function () {
  'use strict';
  const C=window.CEP_COVERAGE, E=window.CEP_ENGINE, KEY='rumoCep.v1', root=document.getElementById('cep-app');
  let view='home', resultId=null, checking=false, pdf=null, pageNo=1, importKind='referencia', materialId=null, editorId=null;
  let data;
  const fresh=()=>({version:1,history:[],session:null,draws:[],overrides:{},drafts:[],materials:[],book:{complete:false,notes:''},activities:{}});
  try {data=JSON.parse(localStorage.getItem(KEY))||fresh();} catch {data=fresh();}
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid=()=>crypto.randomUUID();
  const button=(text,action,value='',primary=false)=>`<button class="button ${primary?'primary':'secondary'}" data-c="${action}" data-value="${esc(value)}">${text}</button>`;
  const notice=s=>`<div class="cep-notice">${s}</div>`;
  const bank=()=>window.CEP_BANK.map(q=>data.overrides[q.id]||q).concat(data.drafts.filter(q=>!window.CEP_BANK.some(x=>x.id===q.id)));
  const scoreBank=()=>bank().concat(Object.values(data.overrides).filter(q=>!window.CEP_BANK.some(x=>x.id===q.id)));
  const current=()=>data.session;
  const date=s=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date(s));
  const duration=s=>`${Math.floor(s/60)}min ${Math.round(s%60)}s`;
  let saveFailed=false;
  function save() {try {localStorage.setItem(KEY,JSON.stringify(data));saveFailed=false; const el=root.querySelector('#cep-save');if(el)el.textContent='Salvo neste aparelho';return true;}catch {saveFailed=true;message('Não foi possível salvar. O armazenamento pode estar cheio; exporte um backup antes de fechar.');return false;}}
  function message(text) {const el=document.getElementById('toast-region'),toast=document.createElement('div');toast.className='toast show';toast.textContent=text;el.replaceChildren(toast);setTimeout(()=>toast.remove(),6500);}
  function db() {return new Promise((resolve,reject)=>{const request=indexedDB.open('rumoCepAssets',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
  async function asset(action,id,value) {const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('assets',action==='get'?'readonly':'readwrite');const req=action==='get'?tx.objectStore('assets').get(id):tx.objectStore('assets').put(value,id);tx.oncomplete=()=>{resolve(req.result);d.close();};tx.onerror=()=>{reject(tx.error);d.close();};});}
  function track() {const s=current();if(!s)return;const now=Date.now();const elapsed=Math.min(60,Math.max(0,(now-(s.lastTick||now))/1000));if(view==='session'&&!root.hidden&&!document.hidden) s.times[s.index]=(s.times[s.index]||0)+elapsed; s.lastTick=now;}
  function shell(body) {
    root.innerHTML=`<header class="cep-header"><div><b>Rumo ao CEP</b><span>Rafael · ingresso no 6º ano em 2027</span></div><nav aria-label="Navegação CEP">${['home','train','review','guide','book','parent','sources'].map((v,i)=>`<button data-c="nav" data-value="${v}" class="${view===v?'selected':''}">${['Início','Treinar','Revisão','Estudo guiado','Mandela','Responsável','Fontes'][i]}</button>`).join('')}</nav></header><main class="cep-page">${body}</main><footer class="cep-footer"><span id="cep-save">${saveFailed?'Falha ao salvar':'Salvo neste aparelho'}</span> · Progresso local, sem sincronização entre aparelhos. Faça backup no painel da responsável. Preparatório independente, sem vínculo com o CEP.</footer>`;
    hydrateAssets();
  }
  async function hydrateAssets() {for(const img of root.querySelectorAll('img[data-asset]')) {try {const src=await asset('get',img.dataset.asset);if(src && img.isConnected) img.src=src;else if(img.isConnected) img.alt='Recurso ausente. Suspenda a questão até restaurar o arquivo.';}catch {message('Não foi possível carregar um recurso local.');}}}
  function visual(q) {if(!q.visual)return '';const html=q.visual.startsWith('asset:')?`<img data-asset="${esc(q.visual.slice(6))}" alt="${esc(q.visualAlt||'Página completa do material fornecido; amplie para ler.')}"/>`:window.CEP_VISUALS[q.visual];return `<figure class="cep-visual">${html}${button('Ampliar imagem','zoom',q.id)}</figure>`;}
  function home() {
    const active=E.active(bank()), h=data.history, total=h.reduce((sum,s)=>sum+E.score(s,scoreBank()).total,0), points=h.reduce((sum,s)=>sum+E.score(s,scoreBank()).points,0);
    shell(`<section class="cep-hero"><div class="eyebrow">Preparação independente · CEP 2027</div><h1>Rafael, leia com calma.<br>Escolha com segurança.</h1><p>Treine interpretação cuidadosa e problemas com várias etapas. Quando duas alternativas parecerem boas, procure a evidência que decide entre elas.</p><div class="cep-actions">${button('Fazer diagnóstico','start','diagnóstico',true)}${button('Simulado de 30 questões','start','simulado')}${button('Treinar por assunto','nav','train')}${button('Paraná e Curitiba: treino avançado','nav','regional')}</div></section>${current()?notice(`Há uma sessão de ${esc(current().mode)} em andamento. ${current().questions.some(q=>q.id.startsWith('cep-'))?'Esta sessão usa o banco anterior; descarte-a para começar com as novas questões. ':''}${button('Continuar de onde parei','resume')}${button('Descartar simulado','discard')}`):''}<div class="cep-grid"><section class="cep-card"><h2>Seu caminho</h2><p>${h.length} sessões entregues · ${total?Math.round(points/total*100)+'% de acertos em itens válidos':'ainda sem respostas registradas'}.</p><p>${active.length} questões disponíveis. Os exercícios são autorais, revisados na implementação; não são provas anteriores do CEP.</p>${button('Ver meus próximos treinos','nav','review')}</section><section class="cep-card"><h2>O simulado CEP</h2><p>10 Português · 10 Matemática · 4 Ciências · 3 Geografia · 3 História.</p><p>Desafio alto: o simulado prioriza 30 questões difíceis. Essa dificuldade é uma escolha do treino, não uma exigência do edital. 30 questões, quatro alternativas, um ponto por acerto e três horas incluindo revisão e cartão-resposta. Correção somente após a entrega. Sem redação obrigatória.</p></section><section class="cep-card"><h2>Leitura obrigatória</h2><p>Mandela: o africano de todas as cores, de Alain Serres e Zaü.</p><p>${data.materials.some(m=>m.kind==='livro')?'Material fornecido. Exercícios sobre a obra dependem de revisão da responsável.':'Pendente de material autorizado. A cobertura de Literatura permanece incompleta.'}</p>${button('Acompanhar a leitura','nav','book')}</section></div>`);
  }
  function filters() {const subject=root.querySelector('#cep-subject')?.value||'', item=root.querySelector('#cep-item')?.value||'',difficulty=root.querySelector('#cep-difficulty')?.value||'',count=Number(root.querySelector('#cep-count')?.value||5);return {subject,item,difficulty,count};}
  function filterForm() {return `<div class="cep-fields"><label>Matéria<select id="cep-subject"><option value="">Todas</option>${Object.entries(C.subjects).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label>Assunto / item do edital<select id="cep-item"><option value="">Todos os assuntos</option>${C.coverage.filter(x=>x.id!=='p13').map(x=>`<option value="${x.id}" data-subject="${x.subject}">${x.id.toUpperCase()} · ${esc(x.label)}</option>`).join('')}</select></label><label>Dificuldade<select id="cep-difficulty"><option value="">Variada</option><option>fácil</option><option>média</option><option selected>difícil</option></select></label><label>Quantidade<select id="cep-count"><option>5</option><option>10</option><option>15</option></select></label></div>`;}
  function train() {shell(`<h1>Treino por assunto</h1>${button('Paraná e Curitiba: treino avançado','nav','regional')}<p>Uma questão por tela. Ao conferir, sua alternativa permanece marcada e fica bloqueada. A correção explica cada opção.</p><section class="cep-card">${filterForm()}<div class="cep-actions">${button('Começar treino','filtered','treino',true)}${button('Desafio de interpretação','start','interpretação')}</div><p class="cep-small">Se o assunto tiver menos questões que a quantidade escolhida, usaremos todas as disponíveis sem repetir. O total será informado ao começar.</p></section><div id="cep-train-detail"></div>`);study.trainDetail();}
  function regional() {
    const R=window.CEP_REGIONAL, available=E.active(bank()).filter(q=>q.collection===R.collection);
    shell(`<div class="eyebrow">História e Geografia · estudo específico</div><h1>Paraná e Curitiba: treino avançado</h1><p>${available.length} questões disponíveis, todas difíceis: compare fontes, calcule intervalos, siga percursos e confronte conclusões com os dados. Os exercícios são autorais; este nível é uma escolha do preparatório.</p><section class="cep-card"><h2>Começar prática</h2><div class="cep-fields"><label>Matéria<select id="cep-regional-subject"><option value="">História e Geografia</option value="historia">História</option><option value="geografia">Geografia</option></select></label><label>Quantidade<select id="cep-regional-count"><option>5</option><option selected>10</option><option>15</option></select></label></div><div class="cep-actions">${button('Treinar Paraná e Curitiba','regional-start','',true)}${button('Revisar meus erros e dúvidas','nav','review')}</div><p class="cep-small">Sem repetição dentro do treino. Questões ainda não vistas recebem prioridade. Respostas e dúvidas entram no histórico e na revisão habitual.</p></section><h2 class="cep-space">Ler para relacionar, não só decorar</h2>${[['marcos','Marcos políticos e histórias anteriores'],['tropas','Tropeirismo: circulação, apoio e comércio'],['urbano','Curitiba: território, relevo, água e clima'],['ambiente','Paisagem e conservação ambiental']].map(([id,title])=>`<details class="cep-card cep-regional-reading"><summary>${title}</summary><p>${esc(R.texts[id])}</p><p class="cep-small">Texto autoral de estudo; referências consultadas abaixo. Não substitui a leitura de documentos quando uma pesquisa exige a fonte original.</p></details>`).join('')}<section class="cep-card"><h2>Exemplo resolvido: duas conclusões quase iguais</h2><p>Uma vila foi instalada em 1693. Em 1853, tornou-se capital provincial. Em 1889, a província passou a estado.</p><ol><li>Defina o que está sendo comparado: existir como vila é diferente de exercer a função de capital.</li><li>Calcule os intervalos: 1853 − 1693 = 160 anos; 1889 − 1853 = 36 anos.</li><li>Compare: o primeiro intervalo supera o segundo em 124 anos. A diferença não é 36; 36 é a duração do segundo.</li></ol><p>“A história da cidade começou em 1853” ignora a vila anterior e a presença humana antes dela. “A função de capital começou em 1853” corresponde ao marco informado.</p>${button('Aprofundar a aula de história local','study-item','h09')}</section><section class="cep-card"><h2>Exemplo resolvido: percentual maior não é quantidade maior</h2><p>Dados fictícios: um bosque tem 200 árvores, sendo 40 araucárias. Retiram-se 40 de outras espécies; nenhuma araucária é plantada ou retirada.</p><ol><li>Antes: 40 de 200 árvores = 20%.</li><li>Depois: 40 de 160 árvores = 25%.</li><li>A participação aumentou; a quantidade de araucárias continua 40. O total de árvores diminuiu.</li></ol><p>Uma alternativa pode acertar o percentual e errar a explicação. Confira as duas partes antes de escolher.</p>${button('Aprofundar território e paisagem','study-item','g05')}</section><h2 class="cep-space">Referências e conferência</h2><p>As duas páginas enviadas foram consultadas. A redação das questões, os exemplos e os desenhos são próprios. Informações divergentes foram conferidas nas fontes oficiais; dados de cenários fictícios estão identificados.</p>${R.references.map(r=>`<details class="cep-card"><summary>${esc(r.name)}</summary><p>${esc(r.note)}</p><a href="${esc(r.url)}" target="_blank" rel="noreferrer">Abrir referência</a></details>`).join('')}`);
  }
  function start(mode, f={count:5}) {
    if(current()) {message('Continue, entregue ou descarte a sessão salva antes de começar outra.');view='home';home();return;}
    try {const questions=E.select(bank(),mode,f,data.history,data.draws);if(f.progressive)questions.sort((a,b)=>['fácil','média','difícil'].indexOf(a.difficulty)-['fácil','média','difícil'].indexOf(b.difficulty));const timed=['simulado','diagnóstico'].includes(mode);const now=Date.now();data.session={id:uid(),mode,questions,answers:questions.map(()=>null),confidence:questions.map(()=>null),flags:questions.map(()=>false),times:questions.map(()=>0),reasons:questions.map(()=>null),firstAnswers:questions.map(()=>null),firstConfidence:questions.map(()=>null),rivals:questions.map(()=>null),revealed:questions.map(()=>false),tries:questions.map(()=>0),index:0,started:now,deadline:timed?now+10800000:null,lastTick:now};data.draws.push(questions.map(q=>q.id));data.draws=data.draws.slice(-100);save();view='session';session();if(!timed&&questions.length<(f.count||5))message(`Este filtro tem ${questions.length} questão(ões) revisada(s); não houve repetição.`);}catch(error){message(error.message);}
  }
  const clockText=()=>{const s=current(),sec=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;};
  function session() {
    const s=current();if(!s){view='home';home();return;}const i=s.index,q=s.questions[i],answered=s.answers.filter(a=>a!==null).length;
    const locked=s.revealed[i],timed=!!s.deadline;
    shell(`<div class="cep-session-head"><div><span class="eyebrow">${esc(s.mode)} · ${C.subjects[q.subject]}</span><h2>Questão ${i+1} de ${s.questions.length}</h2><span>${answered} respondidas · ${s.questions.length-answered} sem resposta</span></div>${timed?`<span class="cep-clock" id="cep-clock" aria-label="Tempo restante">${clockText()}</span>`:''}</div><progress value="${answered}" max="${s.questions.length}" aria-label="Questões respondidas"></progress><div class="cep-session-layout"><article class="cep-card cep-question"><p class="cep-small">${esc(q.difficulty)} · ${esc(q.origin.label)}</p>${q.base?`<section class="cep-base" aria-label="Texto-base"><h3>Texto-base</h3><div>${esc(q.base).replace(/\n/g,'<br>')}</div></section>`:''}${visual(q)}<h2 class="cep-prompt" tabindex="-1">${esc(q.prompt)}</h2><div class="cep-options" role="group" aria-label="Alternativas">${q.options.map((o,j)=>`<button class="cep-option ${s.answers[i]===o.id?'chosen':''}" data-c="answer" data-value="${o.id}" aria-pressed="${s.answers[i]===o.id}" ${locked?'disabled':''}><b>${'ABCD'[j]}</b><span>${esc(o.text)}</span></button>`).join('')}</div><fieldset class="cep-confidence"><legend>Como você escolheu? (opcional)</legend>${[['certeza','Tenho certeza'],['dúvida','Estou em dúvida'],['chute','Chutei']].map(([id,label])=>`<label><input type="radio" name="confidence" value="${id}" ${s.confidence[i]===id?'checked':''} ${locked?'disabled':''}>${label}</label>`).join('')}</fieldset><details class="cep-rival" ${s.confidence[i]==='dúvida'?'open':''}><summary>Registrar a dúvida entre duas alternativas</summary><label>Além da minha escolha, considerei<select id="cep-rival" ${locked?'disabled':''}><option value="">Não registrar</option>${q.options.map((o,j)=>`<option value="${o.id}" ${s.rivals?.[i]===o.id?'selected':''} ${s.answers[i]===o.id?'disabled':''}>${'ABCD'[j]} · ${esc(o.text)}</option>`).join('')}</select></label><p class="cep-small">O registro ajuda a comparar as evidências na revisão; não altera sua resposta.</p></details><div class="cep-actions">${button(s.flags[i]?'Desmarcar revisão':'Marcar para revisar','flag')}${!locked?button('Limpar resposta','clear'):''}${!timed&&!locked?button('Conferir minha resposta','check','',true):''}</div>${!timed&&checking&&!locked?notice(`A alternativa escolhida ainda não está correta. Releia a evidência antes de decidir. ${button('Tentar novamente','retry')}${button('Ver correção explicada','reveal')}`):''}${!timed&&locked?correction(s,i):''}<div class="cep-actions">${i>0?button('Anterior','index',i-1):''}${i<s.questions.length-1?button('Próxima / pular','index',i+1,true):''}${button('Cartão-resposta e entrega','card')}</div></article><aside class="cep-card cep-index"><h3>Navegar</h3><p class="cep-small">● Respondida · ⚑ Revisar<br>Use 1–4 para escolher e as setas para navegar.</p><div class="cep-numbers">${s.questions.map((_,j)=>`<button data-c="index" data-value="${j}" class="${s.answers[j]?'answered':''} ${i===j?'current':''}" aria-label="Questão ${j+1}${s.answers[j]?', respondida':', sem resposta'}${s.flags[j]?', marcada para revisar':''}">${j+1}${s.flags[j]?' ⚑':''}</button>`).join('')}</div>${button('Salvar e sair','nav','home')}${button('Descartar simulado','discard')}</aside></div>`);
  }
  function discard() {
    const previous=current();if(!previous)return;
    if(!confirm('Descartar esta sessão CEP? As respostas e marcações em andamento serão apagadas. Ela não receberá nota nem entrará no histórico. Os resultados anteriores serão mantidos.'))return;
    data.session=null;
    if(!save()){data.session=previous;return;}
    checking=false;resultId=null;view='home';home();message('Sessão descartada. Nenhum resultado foi acrescentado ao histórico.');
  }
  function choose(id) {const s=current();if(!s||view!=='session'||s.revealed[s.index])return;if(s.deadline&&Date.now()>=s.deadline){submit(true);return;} if(!s.questions[s.index].options.some(o=>o.id===id))return; track();s.answers[s.index]=id;if(s.rivals?.[s.index]===id)s.rivals[s.index]=null;checking=false;save();session();}
  function index(i) {track();const s=current();if(!s||i<0||i>=s.questions.length)return;s.index=i;s.lastTick=Date.now();checking=false;save();view='session';session();root.querySelector('.cep-prompt')?.focus();}
  function card() {track();save();const s=current();view='card';shell(`<h1>Cartão-resposta</h1><p>Confira as marcações antes de entregar. O tempo inclui essa revisão.</p>${s.deadline?`<p class="cep-clock" id="cep-clock">${clockText()}</p>`:''}${notice(`${s.answers.filter(a=>a===null).length} questão(ões) sem resposta · ${s.flags.filter(Boolean).length} marcada(s) para revisar. Itens sem resposta valem zero. Correção após a entrega.`)}<section class="cep-card cep-answer-card">${s.questions.map((q,i)=>`<div><button data-c="index" data-value="${i}" class="cep-card-number">${i+1}${s.flags[i]?' ⚑':''}</button><span>${C.subjects[q.subject]}</span>${q.options.map((o,j)=>`<button data-c="card-answer" data-index="${i}" data-value="${o.id}" aria-label="Questão ${i+1}, alternativa ${'ABCD'[j]}" aria-pressed="${s.answers[i]===o.id}" ${s.revealed[i]?'disabled':''} class="${s.answers[i]===o.id?'chosen':''}">${'ABCD'[j]}</button>`).join('')}<button data-c="card-clear" data-value="${i}" ${s.revealed[i]?'disabled':''}>Limpar</button></div>`).join('')}</section><div class="cep-actions">${button('Voltar às questões','index',s.index)}${button('Entregar agora','submit','',true)}${button('Descartar simulado','discard')}</div>`);}
  function submit(expired=false) {const s=current();if(!s)return;track();s.finished=expired&&s.deadline?s.deadline:Date.now();s.expired=expired;data.history.push(s);data.session=null;resultId=s.id;save();view='result';results();if(expired)message('O tempo terminou. A sessão foi entregue com as respostas salvas.');}
  function correction(s,i, report=false) {const scored=E.score(s,scoreBank()).rows[i],q=scored.q,letters=new Map(s.questions[i].options.map((o,j)=>[o.id,'ABCD'[j]])),chosen=q.options.find(o=>o.id===s.answers[i]),right=q.options.find(o=>o.id===q.correctId);return `<section class="cep-correction ${scored.suspended?'pending':scored.correct?'correct':'incorrect'}"><h3>${scored.suspended?'Questão suspensa · fora das métricas':scored.correct?'Resposta correta':'Vamos conferir a evidência'}</h3><p>Você marcou: ${chosen?`${letters.get(chosen.id)} · ${esc(chosen.text)}`:'sem resposta'}.<br>Resposta ${scored.suspended?'em revisão':'correta'}: ${letters.get(right?.id)} · ${esc(right?.text)}.</p>${s.firstAnswers?.[i]&&s.firstAnswers[i]!==s.answers[i]?'<p class="cep-notice">Sua primeira escolha foi diferente. A revisão guardará essa tentativa para ajudar a confirmar a habilidade em outra questão.</p>':''}<p>${esc(q.explanation)}</p><p><strong>Evidência / raciocínio:</strong> ${esc(q.evidence||q.explanation)}</p><ul>${s.questions[i].options.map(o=>{const updated=q.options.find(x=>x.id===o.id)||o;return `<li><strong>${letters.get(o.id)} · ${esc(updated.text)}</strong>: ${esc(updated.explanation)}</li>`;}).join('')}</ul><p class="cep-small">${C.subjects[q.subject]} · ${esc(q.skill)} · Itens ${q.items.join(', ')}.<br>${esc(q.origin.label)}${q.origin.url?` · <a href="${esc(safeUrl(q.origin.url))}" target="_blank" rel="noreferrer">Referência</a>`:''}${q.origin.page?` · página ${esc(q.origin.page)}`:''}</p>${q.origin.references?.length?`<details class="cep-card"><summary>Conferir as fontes desta questão autoral</summary>${q.origin.references.map(r=>`<p>${referenceLink(r.name,r.url)}<br>${esc(r.note)}</p>`).join('')}</details>`:''}<label>O que aconteceu? (sua avaliação)<select data-reason="${i}" data-session="${s.id}"><option value="">Não registrado</option>${['Não conhecia o conteúdo','Interpretei errado','Errei o cálculo','Passei por cima de um detalhe','Fiquei em dúvida'].map(x=>`<option ${s.reasons[i]===x?'selected':''}>${x}</option>`).join('')}</select></label>${window.CEP_LESSONS.byItem[q.items[0]]?button('Retomar a aula desta habilidade','study-item',q.items[0]):''}${button('Contestar / sinalizar questão','contest',`${s.id}:${i}`)}</section>`;}
  function results() {const s=data.history.find(s=>s.id===resultId);if(!s){view='parent';parent();return;}const score=E.score(s,scoreBank());shell(`<h1>${score.points} de ${score.total} pontos</h1><p>${esc(s.mode)} · ${date(s.finished)} · ${duration((s.finished-s.started)/1000)} decorridos. ${score.skipped} puladas · ${score.uncertain} acertos com dúvida ou chute.</p>${score.total<s.questions.length?notice(`${s.questions.length-score.total} item(ns) suspenso(s) retirado(s) das métricas. Resultados são recalculados com a revisão atual.`):''}${button('Revisar habilidades deste histórico','nav','review')}<h2 class="cep-space">Correção explicada</h2>${s.questions.map((q,i)=>`<details class="cep-card"><summary>Questão ${i+1} · ${C.subjects[q.subject]} · ${score.rows[i].suspended?'Suspensa':score.rows[i].correct?'Acerto':score.rows[i].skipped?'Pulada':'Erro'}${['dúvida','chute'].includes(s.confidence[i])?' · baixa confiança':''}</summary>${q.base?`<div class="cep-base">${esc(q.base).replace(/\n/g,'<br>')}</div>`:''}${visual(q)}<h3>${esc(q.prompt)}</h3>${correction(s,i,true)}</details>`).join('')}`);}
  function pending() {return window.CEP_LEARNING.analyze(scoreBank(),data.history,Date.now(),bank()).pending;}
  function review() {study.review();}
  function guide() {study.guide();}
  function openGuide() {study.openGuide();}
  function book() {const materials=data.materials.filter(m=>m.kind==='livro'),questions=E.active(bank()).filter(q=>q.items.includes('p13'));shell(`<h1>Mandela: o africano<br>de todas as cores</h1><p>Alain Serres e Zaü · leitura integral obrigatória.</p>${notice(materials.length?'Material recebido; somente questões fundamentadas nele e revisadas podem ser usadas.':'Pendente de material autorizado. Não há exercícios sobre acontecimentos, linguagem ou ilustrações da obra. Literatura não está completa.')}<section class="cep-card"><p>Os exercícios complementam a leitura; não substituem o livro. Não foram inventadas cenas, citações ou páginas.</p>${button('Importar material autorizado','book-import')}<label><input id="cep-book-complete" type="checkbox" ${data.book.complete?'checked':''}> Rafael concluiu a leitura integral (registro da responsável)</label><label>Diário de leitura<textarea id="cep-book-notes" rows="6" placeholder="Registre dúvidas e observações da leitura; cite a página de sua edição.">${esc(data.book.notes)}</textarea></label>${button('Salvar registro de leitura','book-save')}<p>${questions.length} exercício(s) fundamentado(s) e aprovado(s) pela responsável. O registro de leitura não valida automaticamente os exercícios.</p>${questions.length?button('Treinar a obra','book-train'):''}${materials.map(m=>`<p>${esc(m.name)} ${button('Ver material','material',m.id)}</p>`).join('')}</section>`);}
  function aggregate(key) {const map=new Map();data.history.forEach(s=>E.score(s,scoreBank()).rows.filter(r=>!r.suspended).forEach(r=>{const keys=key==='items'?r.q.items:[r.q[key]];keys.forEach(k=>{const a=map.get(k)||{n:0,right:0,skip:0,low:0,time:0};a.n++;a.right+=Number(r.correct);a.skip+=Number(r.skipped);a.low+=Number(r.correct&&['dúvida','chute'].includes(r.confidence));a.time+=r.seconds;map.set(k,a);});}));return map;}
  function reportTable(key) {const rows=[...aggregate(key)].map(([label,a])=>`<tr><th scope="row">${esc(key==='subject'?C.subjects[label]:key==='items'?`${label.toUpperCase()} · ${C.coverage.find(x=>x.id===label)?.label}`:label)}</th><td>${a.right}/${a.n}</td><td>${a.n-a.right-a.skip}</td><td>${a.skip}</td><td>${a.low}</td><td>${duration(a.time/a.n)}</td><td>${key==='items'?window.CEP_LEARNING.analyze(scoreBank(),data.history,Date.now(),bank()).skills.get(label).status:a.n<5?'Evidência insuficiente':'Confirmar com questões diferentes; consulte a revisão'}</td></tr>`);return rows.length?`<div class="cep-table-scroll"><table class="cep-table"><thead><tr><th>Conteúdo</th><th>Acertos</th><th>Erros</th><th>Puladas</th><th>Acertos com dúvida/chute</th><th>Tempo médio ativo</th><th>Próximo passo</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`:notice('Sem respostas reais para gerar este relatório.');}
  function parent() {const valid=E.active(bank()),cover=new Set(valid.flatMap(q=>q.items));shell(`<h1>Painel da responsável</h1><p>Relatórios calculados a partir das respostas reais. Notas são recalculadas quando uma questão é suspensa ou corrigida. O tempo ativo é aproximado, diferente do tempo total de uma sessão.</p><div class="cep-actions">${button('Exportar progresso e materiais','backup')}${button('Importar backup','restore')}${button('Importar PDF / imagem / gabarito','import')}${button('Revisar e editar questões','editor-list')}</div><input type="file" id="cep-backup-file" accept="application/json" hidden><h2 class="cep-space">Desempenho por matéria</h2>${reportTable('subject')}<details class="cep-card"><summary>Desempenho por assunto</summary>${reportTable('topic')}</details><details class="cep-card"><summary>Desempenho por habilidade do edital</summary>${reportTable('items')}</details><h2 class="cep-space">Histórico e evolução</h2><p>A comparação entre modos e dificuldades exige cuidado. Acertos após tentativa ou consulta no treino são identificados no histórico.</p>${data.history.length?`<div class="cep-table-scroll"><table class="cep-table"><thead><tr><th>Entrega</th><th>Modo</th><th>Resultado atual</th><th>Tempo decorrido</th><th>Consulta / tentativas</th><th>Abrir</th></tr></thead><tbody>${data.history.map(s=>{const r=E.score(s,scoreBank());return `<tr><td>${date(s.finished)}</td><td>${esc(s.mode)}</td><td>${r.points}/${r.total} · ${r.total?Math.round(r.points/r.total*100):0}%</td><td>${duration((s.finished-s.started)/1000)}</td><td>${s.revealed.filter(Boolean).length} correções vistas no treino · ${s.tries.reduce((a,b)=>a+b,0)} tentativas</td><td>${button('Ver correção','result',s.id)}</td></tr>`;}).join('')}</tbody></table></div>`:notice('Nenhuma sessão entregue.')}<h2 class="cep-space">Cobertura do edital</h2><p>${cover.size} de ${C.coverage.length} itens têm ao menos um exercício disponível. Essa contagem não significa cobertura completa dos subtemas; a obra obrigatória está ${valid.some(q=>q.items.includes('p13'))?'com exercícios fornecidos':'pendente'}. ${esc(C.differences)}</p>${Object.entries(C.subjects).map(([subject,label])=>`<details class="cep-card"><summary>${label} · ${valid.filter(q=>q.subject===subject).length} questões disponíveis</summary><ul class="cep-coverage">${C.coverage.filter(x=>x.subject===subject).map(x=>{const n=valid.filter(q=>q.items.includes(x.id)).length;return `<li><strong>${x.id.toUpperCase()} · Anexo II, ${x.section}, p. ${x.page}</strong><br>${esc(x.label)}<br><span class="${n?'':'cep-pending'}">${n?`${n} exercício(s) · cobertura parcial, detalhamento ainda requer ampliação`:'Sem questões verificadas · pendente'}</span>${n?button('Treinar este item','item-train',x.id):''}</li>`;}).join('')}</ul></details>`).join('')}<h2 class="cep-space">Aulas e compreensão inicial</h2><p>${Object.values(data.learning.items).filter(p=>p.reviewedAt).length} habilidades com aula revisitada. ${Object.values(data.learning.items).filter(p=>p.check?.first).length} testes de aula tentados; ${Object.entries(data.learning.items).filter(([id,p])=>p.check?.first?.choice===window.CEP_LESSONS.byItem[id]?.check.correctId).length} corretos na primeira tentativa. Testes de aula não alteram notas dos simulados.</p>${button('Abrir aulas por habilidade','nav','guide')}<h2 class="cep-space">Sugestão de próximos treinos</h2><p>${pending().length?`Revise ${pending().length} questões com erros, omissões ou baixa confiança e depois alterne matérias.`:'Faça um diagnóstico e mantenha treinos variados. Um único acerto não demonstra domínio.'}</p>${button('Abrir revisão personalizada','nav','review')}<h2 class="cep-space">Materiais locais</h2>${data.materials.map(m=>`<p>${esc(m.name)} · ${esc(m.kind)} · ${m.pages} página(s) ${button('Abrir prévia','material',m.id)}</p>`).join('')||'<p>Nenhum material importado.</p>'}<details class="cep-card"><summary>Atividades complementares salvas</summary>${Object.entries(data.activities).map(([id,text])=>`<h3>${esc(C.coverage.find(x=>x.id===id)?.label)}</h3><p class="cep-pre">${esc(text)}</p>`).join('')||'<p>Nenhuma atividade salva.</p>'}</details>`);}
  function safeUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
  function referenceLink(name,url){
    const local=(window.CPM_ARCHIVE||[]).some(entry=>entry.pdf===url);
    return local?button(esc(name),'source-document',url):`<a href="${esc(safeUrl(url))}" target="_blank" rel="noreferrer">${esc(name)}</a>`;
  }
  const sourceRows=[
    ...Object.values(window.CHALLENGE_BANK.references).map(r=>[r.name,r.url,r.note]),
    ['Edital CEP nº 005/2026 · 29 páginas','https://www.cep.pr.gov.br/sites/cep/arquivos_restritos/files/documento/2026-10/edital_0052026_edital_6_ano_fundamental.pdf','Consultado e salvo offline. Matriz: pp. 14–15. Anexo II: pp. 24–28.'],
    ['Editais CEP 2027','https://www.cep.pr.gov.br/Pagina/EDITAIS-ANO-LETIVO-2027','Consultada em 03/10/2026. A página apresenta o edital 005/2026; não foi identificada atualização para o 6º ano nessa consulta. Confira novos comunicados manualmente.'],
    ['CPM Londrina · processo classificatório','https://cpmlondrina.com.br/processo-classificatorio/','Página consultada; lista cadernos e gabaritos definitivos. Referência de outra instituição.'],
    ['CPM Londrina · acervo','https://cpmlondrina.com.br/caderno-de-provas/','Página consultada. O acervo CPM existente foi preservado na aba CPM.'],
    ['CPM 2025/2026 · caderno','https://cpmlondrina.com.br/wp-content/uploads/2025/12/EF-v-11-11.cdr-ensino-fundamentalpdf-1764547187.pdf','PDF consultado, 11 páginas. Nenhuma questão reproduzida no banco CEP.'],
    ['CPM 2024/2025 · caderno','https://cpmlondrina.com.br/wp-content/uploads/2024/12/ensino-fundamentalpdf-24-25pdf-1732488271.pdf','PDF consultado, 10 páginas. Nenhuma questão reproduzida no banco CEP.'],
    ['CPM Londrina 2018 · caderno','https://cpmlondrina.com.br/wp-content/uploads/2018/01/caderno-de-prova-ensino-fundamental-2o-cpm.pdf','PDF consultado, 8 páginas. Nenhuma questão reproduzida no banco CEP.'],
    ['CMC · acervo Cursos Azambuja','https://cursosazambuja.com.br/provas-e-gabaritos-cursos-azambuja/544/colegio-militar-de-curitiba-cmc','Página de acervo consultada. Cadernos individuais não importados para CEP.'],
    ['Prova Paraná · gabaritos','https://www.provaparana.pr.gov.br/Pagina/Gabaritos','Página consultada. Nenhum gabarito usado sem caderno correspondente.'],
    ['IBGE · malha de unidades da federação','https://servicodados.ibge.gov.br/api/v3/malhas/paises/BR?formato=application/vnd.geo%2Bjson&qualidade=minima&intrarregiao=UF','Dados baixados e preservados localmente. Mapa gerado com as 27 geometrias, Paraná: código 41.'],
    ['IBGE · história territorial de Curitiba','https://www.ibge.gov.br/biblioteca/visualizacao/dtb/parana/curitiba.pdf','Fonte de conferência dos marcos territoriais; textos dos exercícios são autorais.'],
    ['Prefeitura de Curitiba · história','https://www.curitiba.pr.gov.br/conteudo/historia-fundacao-e-nome-da-cidade/207','Consultada para os marcos de 1693 e a presença dos tropeiros.'],
    ['Fundação Cultural Palmares · informações quilombolas','https://www.gov.br/palmares/pt-br/departamentos/protecao-preservacao-e-articulacao/informacoes-quilombolas/','Consultada como referência sobre comunidades e resistência.'],
    ['NASA Space Place · Terra','https://spaceplace.nasa.gov/all-about-earth/en/','Conferência de rotação, órbita e Sistema Solar.']
  ].concat(window.CEP_REGIONAL.references.map(r=>[r.name,r.url,r.note]));
  function sources(){shell(`<h1>Fontes e limites</h1><p>Referências conferidas em ${C.checkedAt}. O app não afirma conhecer o estilo da futura prova do CEP. A quantidade do banco e seus níveis de dificuldade são escolhas de implementação.</p>${notice('Banco CEP: '+window.CEP_BANK.length+' questões autorais criadas com apoio de IA e revisadas na implementação, sem revisão humana independente. Zero questões oficiais importadas para o banco CEP. A revisão de conteúdo pode ser continuada no painel.')}<div class="cep-actions">${button('Ler edital offline','edital')}${button('Importar fonte manualmente','import')}</div><p>${esc(C.differences)} Todas as ilustrações de exercícios são autorais, exceto a geometria cartográfica baseada no IBGE. A obra de Mandela não foi reproduzida.</p>${sourceRows.map(([name,url,status])=>`<section class="cep-card"><h3>${referenceLink(name,url)}</h3><p>${esc(status)}</p></section>`).join('')}<section class="cep-card"><h2>Pendências explícitas</h2><ul><li>Material autorizado e exercícios fundamentados na obra obrigatória.</li><li>Ampliação dos detalhes de cada item: ter um exercício não cobre automaticamente todas as relações, gêneros, classes de palavras ou medidas.</li><li>Revisão humana pedagógica independente do banco autoral.</li><li>Sem serviço de geração por IA, conta ou sincronização. Todos os treinos funcionam offline.</li><li>Se uma fonte ficar inacessível, importe PDF ou imagem no painel. A extração começa como rascunho, nunca como validação pedagógica.</li></ul></section>`);}
  function editorList(){view='editor-list';const all=bank();shell(`<h1>Revisão de questões</h1><p>Publicar exige conferir texto, recurso visual, gabarito e justificativas. Uma contestação suspende a questão e abre revisão; não altera automaticamente o gabarito.</p>${button('Criar rascunho autoral','new-draft')}<label>Buscar<input id="cep-search" type="search" placeholder="Identificador, texto ou status"></label><div id="cep-question-list">${all.map(q=>`<section class="cep-card cep-edit-row" data-search="${esc(`${q.id} ${q.prompt} ${q.status}`.toLowerCase())}"><strong>${q.id} · ${esc(q.status)}</strong><p>${esc(q.prompt||'Rascunho importado — enunciado por conferir')}</p>${q.contestation?`<p class="cep-pending">Contestação: ${esc(q.contestation)}</p>`:''}${button('Revisar / editar','edit',q.id)}</section>`).join('')}</div>`);}
  function template(base='',visual=null){return {id:'import-'+uid(),subject:'portugues',topic:'A conferir',skill:'A conferir',items:['p02'],difficulty:'média',base,visual,visualAlt:'Página completa do material fornecido.',prompt:'',options:['a','b','c','d'].map(id=>({id,text:'',explanation:''})),correctId:'',explanation:'',evidence:'',origin:{type:'autoral',label:'Rascunho manual — identificar origem',institution:null,year:null,number:null,page:null,url:null},status:'rascunho',preserveOrder:false};}
  function edit(id){editorId=id;const q=bank().find(q=>q.id===id);view='edit';shell(`<h1>Conferir questão</h1><p>${esc(q.id)} · ${esc(q.status)}. Edite todos os campos abaixo em JSON. Alternativas usam IDs estáveis (a, b, c, d); o gabarito usa correctId. Itens válidos constam no painel de cobertura.</p>${q.visual?visual(q):''}${q.base?`<details class="cep-card"><summary>Texto extraído / OCR para conferir</summary><p class="cep-pre">${esc(q.base)}</p></details>`:''}<label>Dados completos da questão<textarea id="cep-edit-json" class="cep-code" rows="24" spellcheck="false">${esc(JSON.stringify(q,null,2))}</textarea></label><div class="cep-card"><label><input type="checkbox" id="cep-verified-content"> Conferi enunciado, texto-base, imagens completas, conteúdo do edital e uma única resposta defensável.</label><label><input type="checkbox" id="cep-verified-answer"> Conferi cálculo / fatos e justificativas. Para original, usei o gabarito definitivo da mesma instituição, ano e versão e descartei anuladas.</label><label><input type="checkbox" id="cep-verified-rights"> Tenho autorização para reutilizar os textos e as imagens. Questões sobre Mandela estão fundamentadas no material autorizado, com edição, página e evidência registradas.</label></div><div class="cep-actions">${button('Salvar como rascunho','draft-save')}${button('Validar e publicar','publish','',true)}${button('Suspender questão','suspend')}${button('Voltar à lista','editor-list')}</div><div id="cep-edit-errors" role="status"></div>`);}
  function commit(status){let q;try{q=JSON.parse(root.querySelector('#cep-edit-json').value);}catch{message('JSON inválido. Confira aspas e vírgulas.');return;}if(q.id!==editorId){message('O identificador deve ser preservado para recalcular resultados.');return;}
    const prior=bank().find(x=>x.id===editorId);
    if(status==='revisada'&&prior?.options?.length===4&&(!Array.isArray(q.options)||q.options.length!==4||prior.options.some(o=>!q.options.some(next=>next.id===o.id)))){message('Preserve os identificadores das alternativas para manter o vínculo com as respostas anteriores.');return;}
    if(status==='revisada'){const errs=E.validate(q);if(q.items.includes('p13')&&(!data.materials.some(m=>m.kind==='livro')||!q.origin.page||!q.evidence||!q.origin.edition||!q.origin.materialId))errs.push('Obra exige material autorizado importado, materialId, edição, página e evidência.');for(const id of ['content','answer','rights'])if(!root.querySelector('#cep-verified-'+id).checked)errs.push('Marque todas as conferências antes de publicar.');if(q.visual?.startsWith('asset:')&&!data.materials.some(m=>m.assets.includes(q.visual.slice(6))))errs.push('Recurso visual não consta dos materiais locais.');if(errs.length){root.querySelector('#cep-edit-errors').textContent=errs.join(' ');return;}q.review={date:new Date().toISOString(),method:'Conferido e publicado pela responsável neste aparelho.'};}
    q.status=status;if(window.CEP_BANK.some(x=>x.id===q.id))data.overrides[q.id]=q;else{const i=data.drafts.findIndex(x=>x.id===q.id);if(i>=0)data.drafts[i]=q;else data.drafts.push(q);}save();message(status==='revisada'?'Questão publicada; métricas recalculadas.':status==='suspensa'?'Questão suspensa e retirada das métricas.':'Rascunho salvo.');edit(q.id);
  }
  function contest(value){const split=value.lastIndexOf(':'),id=value.slice(0,split),i=Number(value.slice(split+1)),s=[...data.history,current()].find(s=>s?.id===id),q=s.questions[i];const reason=prompt('Descreva sua dúvida sobre o enunciado, a justificativa ou a fonte:');if(!reason?.trim())return;const updated=JSON.parse(JSON.stringify(bank().find(x=>x.id===q.id)||q));updated.status='suspensa';updated.contestation=reason.trim();if(window.CEP_BANK.some(x=>x.id===q.id))data.overrides[q.id]=updated;else{const pos=data.drafts.findIndex(x=>x.id===q.id);if(pos>=0)data.drafts[pos]=updated;else data.drafts.push(updated);}save();editorId=q.id;view='edit';edit(q.id);message('Contestação registrada. Questão suspensa até revisão da justificativa e da fonte.');}
  function importView(kind='referencia'){importKind=kind;view='import';shell(`<h1>Importar com conferência</h1><p>PDFs e imagens ficam neste aparelho. Cada página mantém texto e imagem completos como uma unidade. OCR pode errar: todos os itens importados começam como rascunho.</p><section class="cep-card"><label>Tipo de material<select id="cep-import-kind">${[['referencia','Prova / referência'],['gabarito','Gabarito para conferência'],['livro','Livro / trecho autorizado'],['edital','Atualização do edital']].map(([id,label])=>`<option value="${id}" ${id===kind?'selected':''}>${label}</option>`).join('')}</select></label><label>PDF, foto, imagem ou banco JSON<input id="cep-source-file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,application/json"></label><p>Limite: 25 MB, até 80 páginas por documento. OCR local em português. A prévia permite corrigir a extração e preencher enunciado, alternativas e gabarito antes da publicação.</p><div id="cep-import-status" role="status"></div></section><div id="cep-import-preview"></div>`);}
  const readDataUrl=file=>new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=()=>rej(fr.error);fr.readAsDataURL(file);});
  let pdfLibPromise;
  function pdfLib(){if(!pdfLibPromise)pdfLibPromise=import('../vendor/pdf.mjs').then(lib=>{lib.GlobalWorkerOptions.workerSrc=new URL('../vendor/pdf.worker.mjs',document.currentScript?.src||new URL('cep/app.js',location.href)).href;return lib;});return pdfLibPromise;}
  async function renderPdfPage(doc,n){const page=await doc.getPage(n),vp=page.getViewport({scale:1.4}),canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;return {image:canvas.toDataURL('image/jpeg',.88),text:(await page.getTextContent()).items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')};}
  async function ocr(src,status){const worker=await Tesseract.createWorker('por',1,{workerPath:new URL('vendor/ocr-worker.js',location.href).href,corePath:new URL('vendor/',location.href).href,langPath:new URL('vendor/',location.href).href,gzip:false,workerBlobURL:false,logger:m=>{if(status?.isConnected)status.textContent=`OCR local: ${m.status} ${Math.round((m.progress||0)*100)}%`;}});try{return (await worker.recognize(src)).data.text;}finally{await worker.terminate();}}
  async function importFile(file){if(!file)return;const status=root.querySelector('#cep-import-status');const kind=root.querySelector('#cep-import-kind')?.value||importKind;try{if(file.size>25*1024*1024)throw Error('O limite é 25 MB por arquivo.');status.textContent='Lendo material local…';if(file.type==='application/json'||file.name.endsWith('.json')){const rows=JSON.parse(await file.text());const arr=Array.isArray(rows)?rows:rows.questions;if(!Array.isArray(arr)||arr.length>500)throw Error('Use uma lista JSON de até 500 questões.');arr.forEach(row=>{const q={...template(),...row,id:'import-'+uid(),status:'rascunho',visual:null};data.drafts.push(q);});save();editorList();message(`${arr.length} rascunhos importados. Recursos visuais de JSON devem ser anexados localmente antes da publicação.`);return;}
      const material={id:uid(),name:file.name,kind,pages:0,assets:[],texts:[],draftIds:[]};
      if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){const lib=await pdfLib(),doc=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;try{if(doc.numPages>80)throw Error('Documento acima de 80 páginas. Importe partes menores.');material.pages=doc.numPages;for(let n=1;n<=doc.numPages;n++){status.textContent=`Preservando página ${n} de ${doc.numPages}…`;const r=await renderPdfPage(doc,n);if(r.text.trim().length<25)r.text=await ocr(r.image,status);const aid=material.id+'-'+n;await asset('put',aid,r.image);material.assets.push(aid);material.texts.push(r.text);}}finally{await doc.destroy();}}
      else if(['image/png','image/jpeg','image/webp'].includes(file.type)){material.pages=1;const src=await readDataUrl(file);const aid=material.id+'-1';await asset('put',aid,src);material.assets.push(aid);material.texts.push(await ocr(src,status));}
      else throw Error('Formato não aceito. Use PDF, PNG, JPEG, WebP ou JSON.');
      material.texts.forEach((text,i)=>{if(kind==='referencia'){const q=template(text,'asset:'+material.assets[i]);q.origin={type:'original',label:`Importado de ${file.name} · origem a conferir`,page:i+1,materialId:material.id};material.draftIds.push(q.id);data.drafts.push(q);}});data.materials.push(material);save();materialId=material.id;pageNo=1;showMaterial();message('Material preservado. Nenhuma questão foi validada automaticamente.');
    }catch(error){if(status?.isConnected)status.textContent='Falha: '+error.message;message('Importação não concluída: '+error.message);}}
  function showMaterial(){const m=data.materials.find(m=>m.id===materialId);if(!m)return;view='material';pageNo=Math.max(1,Math.min(pageNo,m.pages));shell(`<h1>${esc(m.name)}</h1><p>${esc(m.kind)} · Página ${pageNo} de ${m.pages}. Confira texto/OCR e imagem lado a lado.</p><div class="cep-actions">${pageNo>1?button('Página anterior','material-page',pageNo-1):''}${pageNo<m.pages?button('Página seguinte','material-page',pageNo+1):''}${button('Voltar ao painel','nav','parent')}</div><div class="cep-grid"><figure class="cep-card cep-material"><img data-asset="${esc(m.assets[pageNo-1])}" alt="Página ${pageNo} completa do material fornecido">${button('Ampliar página','material-zoom')}</figure><section class="cep-card"><label>Texto extraído / OCR<textarea id="cep-material-text" rows="20">${esc(m.texts[pageNo-1])}</textarea></label>${button('Salvar conferência do texto','material-save')}${m.draftIds[pageNo-1]?button('Editar rascunho desta página','edit',m.draftIds[pageNo-1]):button('Criar questão desta página','material-draft')}<p>Texto da página não substitui enunciado e alternativas. A publicação exige revisão. Nunca associe um gabarito de outra edição ou versão.</p>${m.kind==='edital'?notice('Atualização importada para conferência manual. Não alteramos a matriz ou a cobertura automaticamente; uma diferença oficial precisa ser reconciliada antes de usar o novo formato.') :''}</section></div>`);}
  async function showEdital(){try{view='edital';shell('<h1>Edital CEP nº 005/2026</h1><div id="cep-pdf-status">Carregando cópia local…</div><div id="cep-pdf-controls"></div><figure class="cep-card cep-pdf"><canvas id="cep-pdf-canvas" aria-label="Página do edital"></canvas></figure>');if(!pdf){const lib=await pdfLib();pdf=await lib.getDocument({url:'documents/cep-edital-005-2026.pdf',isEvalSupported:false}).promise;}pageNo=1;await editalPage();}catch(e){message('Não foi possível abrir o edital: '+e.message);}}
  async function editalPage(){const n=pageNo;root.querySelector('#cep-pdf-status').textContent=`Página ${n} de ${pdf.numPages}`;root.querySelector('#cep-pdf-controls').innerHTML=`<div class="cep-actions">${n>1?button('Página anterior','pdf-page',n-1):''}${n<pdf.numPages?button('Página seguinte','pdf-page',n+1):''}${button('Anexo II','pdf-page',24)}${button('Voltar às fontes','nav','sources')}</div>`;const p=await pdf.getPage(n),canvas=root.querySelector('#cep-pdf-canvas'),vp=p.getViewport({scale:1.4});canvas.width=vp.width;canvas.height=vp.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;}
  async function zoom(html){const dialog=document.createElement('dialog');dialog.className='cep-zoom';dialog.innerHTML=`${button('Fechar ampliação','zoom-close')}<div>${html}</div>`;dialog.addEventListener('click',e=>{if(e.target.closest('[data-c="zoom-close"]')){dialog.close();dialog.remove();}});dialog.addEventListener('cancel',()=>dialog.remove());document.body.append(dialog);dialog.showModal();for(const img of dialog.querySelectorAll('[data-asset]'))img.src=await asset('get',img.dataset.asset);}
  async function backup(){try {const assets={};for(const m of data.materials)for(const id of m.assets)assets[id]=await asset('get',id);const payload=JSON.stringify({app:'rumo-cep',version:1,data,assets},null,2);if(window.mobile?.isNative){await window.mobile.exportBackup(payload);message('Backup CEP preparado para salvar ou compartilhar.');}else if(window.desktop?.saveBackup){const r=await window.desktop.saveBackup(payload);if(!r.canceled)message('Backup CEP salvo, incluindo sessão, histórico e materiais.');}else{const url=URL.createObjectURL(new Blob([payload],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='rumo-cep-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Backup gerado. Confira o arquivo baixado.');}}catch(e){message('Falha ao exportar: '+e.message);}}
  function validateBackup(b){if(b?.app!=='rumo-cep'||b.version!==1||b.data?.version!==1||!b.assets||typeof b.assets!=='object')throw Error('Formato de backup CEP inválido.');const d=b.data;if(!Array.isArray(d.history)||!Array.isArray(d.drafts)||!Array.isArray(d.draws)||!Array.isArray(d.materials)||!d.overrides||!d.book||!d.activities)throw Error('Dados incompletos.');for(const s of [...d.history,...(d.session?[d.session]:[])]){if(!s.id||!Array.isArray(s.questions)||!s.questions.length||!Number.isFinite(s.started)||!Number.isInteger(s.index)||s.index<0||s.index>=s.questions.length)throw Error('Sessão inválida.');for(const field of ['answers','confidence','times','flags','reasons','revealed','tries'])if(!Array.isArray(s[field])||s[field].length!==s.questions.length)throw Error('Sessão incompleta.');s.questions.forEach((q,i)=>{if(E.validate(q).length||s.answers[i]!==null&&!q.options.some(o=>o.id===s.answers[i]))throw Error('Questão ou resposta inválida no histórico.');});}
    for(const session of [...d.history,...(d.session?[d.session]:[])])for(const field of ['firstAnswers','firstConfidence','rivals'])if(session[field]!==undefined){if(!Array.isArray(session[field])||session[field].length!==session.questions.length)throw Error('Registro de aprendizagem incompleto.');if(field!=='firstConfidence'&&session[field].some((value,i)=>value!==null&&!session.questions[i].options.some(o=>o.id===value)))throw Error('Alternativa de aprendizagem inválida.');}
    if(d.learning){if(typeof d.learning!=='object'||!d.learning.items||Array.isArray(d.learning.items)||!d.learning.notes||Array.isArray(d.learning.notes))throw Error('Progresso das aulas inválido.');for(const [id,p]of Object.entries(d.learning.items)){if(!window.CEP_LESSONS.byItem[id]||!Number.isInteger(p.step)||p.step<0||p.step>3||!p.check||!Array.isArray(p.check.order)||p.check.order.length!==4||new Set(p.check.order).size!==4||p.check.order.some(x=>!['a','b','c','d'].includes(x)))throw Error('Teste de aula incompleto.');}}
    for(const m of d.materials)if(!Array.isArray(m.assets)||m.assets.length!==m.pages||!Array.isArray(m.texts)||m.texts.length!==m.pages||m.assets.some(id=>typeof b.assets[id]!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(b.assets[id])))throw Error('Material incompleto no backup.');for(const q of Object.values(d.overrides))if(q.status==='revisada'&&E.validate(q).length)throw Error('Questão publicada inválida.');return d;}
  async function restoreText(text){try{const b=JSON.parse(text),next=validateBackup(b);if(!confirm(`Restaurar ${next.history.length} sessões e ${next.materials.length} materiais? O progresso CEP atual será substituído. Exporte um backup antes, se precisar guardá-lo.`))return;for(const [id,src] of Object.entries(b.assets))await asset('put',id,src);const previous=data;data=next;study.ensure();if(!save()){data=previous;return;}message('Backup CEP restaurado.');view='parent';parent();}catch(e){message('Backup não restaurado: '+e.message);}}
  function navigate(next){if(current()?.deadline&&!['home','sources'].includes(next)){message('Entregue o simulado em andamento para abrir treinos, exemplos resolvidos e correções. Seu progresso está salvo.');return;}track();save();checking=false;view=next;({home,train,review,guide,book,parent,sources,regional})[next]?.();}
  const study=window.CEP_STUDY.create({root,C,E,esc,button,shell,save,message,bank,scoreBank,start,data:()=>data,visual,hydrateAssets,openGuide:()=>{view='guide';guide();}});
  root.addEventListener('click',async event=>{const el=event.target.closest('[data-c]');if(!el)return;const a=el.dataset.c,v=el.dataset.value;if(el.disabled)return;try{
    if(a==='discard'){discard();return;}
    if(current()?.deadline&&Date.now()>=current().deadline){submit(true);return;}
    if(study.click(a,v))return;
    if(a==='regional-start')start('treino',{collection:window.CEP_REGIONAL.collection,subject:root.querySelector('#cep-regional-subject')?.value||'',difficulty:'difícil',count:Number(root.querySelector('#cep-regional-count')?.value||10)});
    if(a==='nav')navigate(v);if(a==='start')start(v);if(a==='filtered')start(v,filters());if(a==='resume'){view='session';if(current())current().lastTick=Date.now();session();}if(a==='answer')choose(v);if(a==='index')index(Number(v));if(a==='flag'){current().flags[current().index]=!current().flags[current().index];save();session();}if(a==='clear'&&!current().revealed[current().index]){current().answers[current().index]=null;save();session();}if(a==='card')card();if(a==='card-answer'&&!current().revealed[Number(el.dataset.index)]){current().answers[Number(el.dataset.index)]=v;save();card();}if(a==='card-clear'&&!current().revealed[Number(v)]){current().answers[Number(v)]=null;save();card();}
    if(a==='submit'){const n=current().answers.filter(a=>a===null).length;if(confirm(`Entregar agora? ${n} questão(ões) sem resposta. Após a entrega, não será possível alterar as respostas desta sessão.`))submit();}
    if(a==='check'){const s=current(),i=s.index;if(s.revealed[i])return;if(!s.answers[i]){message('Escolha uma alternativa antes de conferir.');return;}s.firstAnswers||=s.questions.map(()=>null);s.firstConfidence||=s.questions.map(()=>null);if(s.firstAnswers[i]===null){s.firstAnswers[i]=s.answers[i];s.firstConfidence[i]=s.confidence[i];}s.tries[i]++;s.revealed[i]=true;checking=false;save();session();}if(a==='reveal'&&!current().deadline){current().revealed[current().index]=true;checking=false;save();session();}
    if(a==='subject-train')start('treino',{subject:v,count:5});if(a==='item-train')start('treino',{item:v,count:5});if(a==='guide-open')openGuide();if(a==='guided-train'){start('guiado',{item:v,count:5});if(current()){current().questions.sort((a,b)=>['fácil','média','difícil'].indexOf(a.difficulty)-['fácil','média','difícil'].indexOf(b.difficulty));save();session();}}
    if(a==='activity-save'){const field=root.querySelector('#cep-activity');data.activities[field.dataset.item]=field.value;save();message('Atividade salva para a responsável ler.');}if(a==='book-save'){data.book.complete=root.querySelector('#cep-book-complete').checked;data.book.notes=root.querySelector('#cep-book-notes').value;save();message('Registro de leitura salvo.');}if(a==='book-import')importView('livro');if(a==='book-train')start('treino',{item:'p13',count:5});
    if(a==='result'){resultId=v;view='result';results();}if(a==='editor-list')editorList();if(a==='new-draft'){const q=template();data.drafts.push(q);save();edit(q.id);}if(a==='edit')edit(v);if(a==='draft-save')commit('rascunho');if(a==='publish')commit('revisada');if(a==='suspend')commit('suspensa');if(a==='contest')contest(v);if(a==='import')importView();if(a==='material'){materialId=v;pageNo=1;showMaterial();}if(a==='material-page'){pageNo=Number(v);showMaterial();}
    if(a==='material-save'){const m=data.materials.find(x=>x.id===materialId);m.texts[pageNo-1]=root.querySelector('#cep-material-text').value;const q=data.drafts.find(x=>x.id===m.draftIds[pageNo-1]);if(q&&q.status==='rascunho')q.base=m.texts[pageNo-1];save();message('Texto conferido salvo; nenhum gabarito foi aprovado.');}
    if(a==='material-draft'){const m=data.materials.find(x=>x.id===materialId),q=template(m.texts[pageNo-1],'asset:'+m.assets[pageNo-1]);q.origin.materialId=m.id;q.origin.page=pageNo;if(m.kind==='livro'){q.items=['p13'];q.origin.edition='Preencher edição';}data.drafts.push(q);save();edit(q.id);}
    if(a==='source-document'){const entry=(window.CPM_ARCHIVE||[]).find(entry=>entry.pdf===v);if(!entry)throw Error('Documento não encontrado.');await zoom(`<h2>${esc(entry.title)}</h2>${entry.pages.map((page,i)=>`<img src="${esc(page)}" alt="Página ${i+1} de ${entry.pages.length}" loading="lazy">`).join('')}`);}if(a==='edital')await showEdital();if(a==='pdf-page'){pageNo=Number(v);await editalPage();}if(a==='zoom'){const q=bank().find(q=>q.id===v)||[...data.history,...(current()?[current()]:[])].flatMap(s=>s.questions).find(q=>q.id===v);if(!q)throw Error('Questão não encontrada.');await zoom(visual(q).replace(/<button[\s\S]*?<\/button>/g,''));}if(a==='material-zoom'){const m=data.materials.find(x=>x.id===materialId);await zoom(`<img data-asset="${esc(m.assets[pageNo-1])}" alt="Página completa do material">`);}
    if(a==='backup')await backup();if(a==='restore'){if(window.desktop?.loadBackup){const r=await window.desktop.loadBackup();if(!r.canceled)await restoreText(r.content);}else root.querySelector('#cep-backup-file').click();}
  }catch(error){message('Não foi possível concluir: '+error.message);}});
  root.addEventListener('change',event=>{const el=event.target;if(el.name==='confidence'&&current()&&!current().revealed[current().index]){current().confidence[current().index]=el.value;const detail=root.querySelector('.cep-rival');if(detail)detail.open=el.value==='dúvida';save();}if(el.id==='cep-subject'){for(const option of root.querySelector('#cep-item').options)option.hidden=!!el.value&&!!option.dataset.subject&&option.dataset.subject!==el.value;root.querySelector('#cep-item').value='';}if(el.dataset.reason){const s=[...data.history,current()].find(s=>s?.id===el.dataset.session);if(s){s.reasons[Number(el.dataset.reason)]=el.value;save();}}if(el.id==='cep-rival'&&current()&&!current().revealed[current().index]){current().rivals||=current().questions.map(()=>null);current().rivals[current().index]=el.value||null;save();}study.change(event);if(el.id==='cep-source-file')importFile(el.files[0]);if(el.id==='cep-backup-file'&&el.files[0])el.files[0].text().then(restoreText);});
  root.addEventListener('input',event=>{study.input(event);if(event.target.id==='cep-search'){const text=event.target.value.toLowerCase();root.querySelectorAll('.cep-edit-row').forEach(el=>{el.hidden=!el.dataset.search.includes(text);});}if(event.target.id==='cep-activity'){data.activities[event.target.dataset.item]=event.target.value;save();}if(event.target.id==='cep-book-notes'){data.book.notes=event.target.value;save();}});
  document.addEventListener('keydown',event=>{if(root.hidden||view!=='session'||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;if(['1','2','3','4'].includes(event.key)){event.preventDefault();choose(current().questions[current().index].options[Number(event.key)-1].id);}if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();index(current().index+(event.key==='ArrowLeft'?-1:1));}});
  setInterval(()=>{if(current()){track();if(current().deadline&&Date.now()>=current().deadline)submit(true);else{const el=root.querySelector('#cep-clock');if(el)el.textContent=clockText();save();}}},1000);
  window.addEventListener('beforeunload',()=>{track();save();});document.addEventListener('visibilitychange',()=>{track();if(current())current().lastTick=Date.now();save();});
  window.CEP_APP={show:()=>{if(current()?.deadline&&Date.now()>=current().deadline)submit(true);else if(view==='home')home();},back:()=>navigate('home'),validateBackup};
  home();
  save();
})();
